"use strict";
const TABS = [["overview", "Overview"], ["media", "Media & matches"], ["claims", "Claims"], ["evidence", "Evidence"], ["ai", "AI assistance"], ["report", "Conclusion & report"], ["notes", "Notes"], ["history", "History"]];
const STYPE = { appeal: "call to action", opinion: "opinion", prediction: "prediction", satire: "satire or humour", question: "question" };
const STYPE_HELP = { opinion: "Looks like an opinion or value judgement, which cannot be shown true or false. If so, remove it (it stays on record), or assess it as insufficient evidence and say why. Check any facts it relies on as separate claims.",
  prediction: "Looks like a prediction, which cannot be verified yet. Check the facts it is based on as separate claims.",
  satire: "Marked as satire or humour. Check whether it is being shared as if it were real; that is the claim to verify.",
  appeal: "A call to share, forward or send something is not a claim by itself. Remove it, but note it: urgency and pressure to share are common in misleading posts and scams.",
  question: "A question is not a claim by itself. Turn any statement it implies into a separate claim." };
const FLOW = ["draft", "analysing", "analyst_review", "awaiting_approval", "approved", "archived"];

async function pageCase(el, [id, tabArg], { isCurrent }) {
  const tab = TABS.some(t => t[0] === tabArg) ? tabArg : "overview";
  let C, P, N, NOTES = [], unsub = null;
  const load = async () => { C = await Svc.getCase(id); P = permsFor(C); NOTES = await Svc.listNotes(id).catch(() => []); N = await names([...NOTES.map(n => n.author),C.assigned_to, C.created_by, C.submitted_by, C.decided_by, ...C.audit.map(a => a.uid), ...C.claims.map(x => x.assessed_by), ...C.evidence.map(e => e.decided_by), ...(C.aiRuns || []).map(r => r.requested_by), PL.config.ownerId, ...Object.keys(PL.config.members || {})]); };
  try { await load(); } catch (e) { el.innerHTML = `<div class="callout bad"><div><b>Case not available.</b> ${esc(errMsg(e))}</div></div>`; return; }
  const reload = async () => { await load(); if (isCurrent()) draw(); };
  const act = async (fn, ok) => { try { await fn(); if (ok) toast(ok); } catch (e) { fail(e); } await reload(); navCounts(); };
  // live updates from teammates
  try { let first = true; unsub = PL.db.doc(`cases/${id}`).onSnapshot(s => { if (!isCurrent()) { unsub?.(); return; } if (first) { first = false; return; } if (s.exists && s.data().version !== C.version && !s.metadata?.hasPendingWrites && !PL.mine.has(`${id}:${s.data().version}`)) { toast("This case was updated by a teammate."); reload(); } }, () => {}); } catch {}

  function draw() {
    crumbs(`<a href="#/cases">Cases</a> / <b>${esc(C.id)}</b>`);
    const pend = C.evidence.filter(e => e.status === "suggested").length, un = C.claims.filter(x => !x.removed && x.assessment === "unassessed").length;
    el.innerHTML = `${header()}${App.guided() ? nextStep() : ""}<nav class="tabs" aria-label="Case sections">${TABS.map(([k, l]) => `<a href="#/case/${esc(C.id)}/${k}" class="${k === tab ? "on" : ""}">${l}${k === "claims" && un ? `<span class="count">${un}</span>` : ""}${k === "evidence" && pend ? `<span class="count">${pend}</span>` : ""}${k === "notes" && NOTES.filter(n => !n.deleted).length ? `<span class="count grey">${NOTES.filter(n => !n.deleted).length}</span>` : ""}</a>`).join("")}</nav><div id="tabBody"></div>`;
    bindHeader();
    const body = $("#tabBody");
    Promise.resolve(({ overview, media, claims, evidence, ai, report, notes, history })[tab](body)).catch(e => { body.innerHTML = `<div class="callout bad"><div>${esc(errMsg(e))}</div></div>`; console.error(e); });
  }
  // guided mode: the one next thing to do
  function nextStep() {
    const c = C, active = c.claims.filter(x => !x.removed), pend = c.evidence.filter(e => e.status === "suggested").length, un = active.filter(x => x.assessment === "unassessed"), nr = active.filter(x => x.assessment !== "unassessed" && !String(x.rationale || "").trim());
    const goT = (tab, label, primary = true) => `<a class="btn sm${primary ? " primary" : ""}" href="#/case/${esc(c.id)}/${tab}">${label}</a>`;
    let n = 0, t = "", d = "", b = "";
    if (c.status === "draft") { n = 1; t = c.media.length ? "Run the automatic checks" : "Add the picture or video, if there is one, then run the checks"; d = c.media.length ? "AIVS splits the text into separate claims and compares the media with the reference archive and earlier cases. Results arrive as suggestions for you to review." : "Images and video are optional. With text only, AIVS still splits it into separate claims."; b = P.edit ? `${c.media.length ? "" : goT("media", "Add media", false)} <button class="btn sm primary" data-a="analyse">Run checks</button>` : ""; }
    else if (c.status === "analysing") { n = 1; t = "Checks are running"; d = "This page updates when they finish."; }
    else if (c.status === "analysis_failed") { n = 1; t = "The checks failed. Retry them"; d = esc(c.analysis_error || ""); b = P.edit ? `<button class="btn primary sm" data-a="analyse">Retry</button>` : ""; }
    else if (c.status === "analyst_review") {
      if (pend) { n = 2; t = `Review ${pend} suggestion${pend > 1 ? "s" : ""}`; d = "Accept what is relevant, dismiss the rest, and say which claim each one supports or contradicts. Suggestions count for nothing until you accept them."; b = goT("evidence", "Open evidence"); }
      else if (un.length) { n = 3; t = `Assess ${un.length} claim${un.length > 1 ? "s" : ""}`; d = "Decide for each claim whether the evidence supports it, contradicts it, or is not enough, and write one or two sentences saying why. Opinions, predictions and calls to share are flagged for you."; b = goT("claims", "Open claims"); }
      else if (nr.length) { n = 3; t = "Explain your assessments"; d = `Claim ${nr.map(x => x.seq).join(", ")} still need a short rationale.`; b = goT("claims", "Open claims"); }
      else { n = 4; t = "Write the conclusion and submit it"; d = `Choose the overall conclusion (AIVS tells you which one the claim assessments lead to), explain it, list what remains uncertain, then submit${LOCAL ? "" : " for review by a different person"}.`; b = goT("report", "Open conclusion"); }
    }
    else if (c.status === "awaiting_approval") { n = 5; t = P.approve ? (LOCAL ? "Acknowledge the conclusion" : "Review and decide") : "Waiting for a reviewer"; d = P.approve ? "Read the draft report, check the claims and evidence, then decide." : "A reviewer who did not work on this case will approve it or return it with comments."; b = P.approve ? goT("report", "Review") : ""; }
    else { n = 6; t = c.status === "approved" ? "Done: the report is frozen" : "Archived"; d = "View or download the report from the Conclusion tab. If new information appears, open a new revision; the frozen report stays unchanged."; b = goT("report", "View report"); }
    const steps = ["Add material", "Review suggestions", "Assess claims", "Conclude", "Review", "Done"];
    return `<div class="nextstep" role="region" aria-label="Next step"><div class="ns-steps">${steps.map((x, i) => `<span class="${i + 1 < n ? "done" : i + 1 === n ? "cur" : ""}">${i + 1}. ${x}</span>`).join("")}</div>
      <div class="ns-body"><div><div class="ns-label">Next step</div><b>${esc(t)}</b><div class="small muted">${d}</div></div><div class="row">${b}</div></div>
      <div class="tiny sub" style="margin-top:6px">Guided mode. Switch to Advanced at the top for every tool at once.</div></div>`;
  }
  function header() {
    const idx = FLOW.indexOf(C.status === "analysis_failed" ? "analysing" : C.status);
    const steps = FLOW.map((s, i) => `<div class="${i < idx ? "done" : i === idx ? (C.status === "analysis_failed" ? "fail" : "cur") : ""}">${i < idx ? "✓ " : ""}${s === "analysing" && C.status === "analysis_failed" ? "Analysis failed" : STATUS[s]}</div>`).join("");
    const staff = [...new Set([PL.config.ownerId, ...Object.entries(PL.config.members || {}).filter(([, r]) => r !== "viewer").map(([i]) => i), C.assigned_to].filter(Boolean))];
    const stuck = C.status === "analysing" && Date.now() - new Date(C.analysis_started || C.updated_at) > 120e3;
    let a = "";
    if (C.status === "draft" && P.edit) a = `<button class="btn primary" data-a="analyse">Run local analysis</button>`;
    if (C.status === "analysing") a = stuck && canEditCase(C) ? `<button class="btn primary" data-a="unstick">Analysis interrupted — retry</button>` : `<span class="chip info"><span class="spin"></span> Analysing…</span>`;
    if (C.status === "analysis_failed" && P.edit) a = `<button class="btn primary" data-a="analyse">Retry analysis</button>`;
    if (C.status === "analyst_review" && P.edit) a = `<button class="btn" data-a="analyse">Re-run checks</button><a class="btn primary" href="#/case/${esc(C.id)}/report">Prepare conclusion</a>`;
    if (C.status === "awaiting_approval") a = P.approve ? `<a class="btn primary" href="#/case/${esc(C.id)}/report">Review and decide</a>` : `<span class="chip warn">${P.ownWork ? "Waiting for a different reviewer" : "Waiting for a reviewer"}</span>`;
    if (["approved", "archived"].includes(C.status)) a = `${P.archive ? `<button class="btn" data-a="archive">Archive case</button>` : ""}${C.status === "approved" && can("archive.manage") ? `<button class="btn" data-a="toArchive">Add media to reference archive</button>` : ""}${P.revise ? `<button class="btn" data-a="revise">Open new revision</button>` : ""}${C.reports?.length ? `<button class="btn primary" data-a="approvedReport">Approved report</button>` : ""}`;
    return `<div class="casehead">${C.is_training ? `<div class="callout train" style="margin-bottom:10px"><div><b>Training case.</b> Synthetic material for practice; not an operational assessment.</div></div>` : ""}
      <div class="top"><div style="min-width:0"><div class="id">${esc(C.id)} · revision ${C.revision} · version ${C.version}</div><h1 style="margin-top:2px">${esc(C.title)}</h1></div><div class="acts">${a}${PL.downloads ? `<button class="btn ghost" data-a="exportPkg" title="Save this case, its files, notes and approved reports as one file to hand over to another AIVS">${icon("share")} Export case</button>` : ""}</div></div>
      <div class="facts"><span>${status(C.status)} ${concl(["awaiting_approval", "approved", "archived"].includes(C.status) ? C.conclusion : null)}</span><span>Priority: ${pri(C.priority)}</span>
        <span>Analyst: ${P.assign ? `<select id="assignSel" style="display:inline-block;width:auto;padding:2px 6px;font-size:13px" aria-label="Assigned analyst"><option value="">Unassigned</option>${staff.map(u => `<option value="${esc(u)}" ${u === C.assigned_to ? "selected" : ""}>${esc(N(u))}</option>`).join("")}</select>` : `<b>${esc(C.assigned_to ? N(C.assigned_to) : "Unassigned")}</b>`}</span><span>Source: <b>${esc(C.source_platform)}</b></span><span>Received: <b>${fmtDT(C.received_at)}</b></span></div>
      <div class="stepper">${steps}</div>
      ${C.status === "analysis_failed" ? `<div class="callout bad" style="margin-top:12px"><div><b>Analysis failed${C.analysis_attempts > 1 ? ` (attempt ${C.analysis_attempts})` : ""}.</b> ${esc(C.analysis_error || "")} Nothing was lost; retry when ready.</div></div>` : ""}
      ${C.reviewer_comment && C.status === "analyst_review" ? `<div class="callout warn" style="margin-top:12px"><div><b>${C.decided_by ? "Returned by reviewer" : "Revision note"}:</b> ${esc(C.reviewer_comment)}</div></div>` : ""}</div>`;
  }
  function bindHeader() {
    $$(".casehead [data-a], .nextstep [data-a]").forEach(b => b.onclick = async () => {
      const a = b.dataset.a;
      if (a === "analyse" || a === "unstick") { b.disabled = true; b.innerHTML = '<span class="spin"></span> Analysing…'; if (a === "unstick") await Svc.mutate(C.id, "Interrupted analysis reset", c => { c.status = "analysis_failed"; c.analysis_error = "The previous analysis was interrupted (the page was closed)."; }).catch(() => {}); return act(() => Svc.analyse(C.id), "Analysis finished."); }
      if (a === "archive" && await confirmBox("Archive this case?", "Archived cases stay searchable and can be reopened as a new revision.", "Archive")) act(() => Svc.archiveCase(C.id), "Case archived.");
      if (a === "revise") { const r = await modal("Open a new revision", `<p class="small">The approved report stays on record unchanged. The case returns to analyst review as revision ${C.revision + 1}.</p><label class="f" for="rr">Reason <span class="req">*</span></label><textarea id="rr" rows="3"></textarea>`, [{ label: "Cancel", value: null }, { label: "Open revision", kind: "primary", validate: m => (!$("#rr", m).value.trim() ? "Give a reason." : null), value: m => $("#rr", m).value.trim() }]); if (r.value) act(() => Svc.revise(C.id, r.value), "Revision opened."); }
      if (a === "approvedReport") { const r = await Svc.getReport(C.reports.at(-1).id); showReport(JSON.parse(r.json), true, `${r.id} · SHA-256 ${r.sha256.slice(0, 16)}…`); }
      if (a === "toArchive") toArchive();
      if (a === "exportPkg") {
        b.disabled = true; b.innerHTML = '<span class="spin"></span> Packaging…';
        try {
          const pkg = await Svc.exportCase(C.id), blob = new Blob([JSON.stringify(pkg)], { type: "application/json" });
          await PL.downloads.save({ filename: `aivs-case-${C.id}-v${C.version}.json`, data: blob });
          toast(`Case package saved (${kb(blob.size)}). Import it on the Cases page of another AIVS. Anyone holding the file can read the case, so share it only through approved channels.`);
        } catch (e) { if (!["declined", "cancelled"].includes(e?.code)) fail(e); }
        b.disabled = false; b.innerHTML = `${icon("share")} Export case`;
      }
    });
    const s = $("#assignSel"); if (s) s.onchange = () => act(() => Svc.assign(C.id, s.value || null), "Assignment updated.");
  }
  async function toArchive() {
    const imgs = C.media.filter(m => m.kind === "image"); if (!imgs.length) return toast("This case has no images or frames to archive.", "err");
    const r = await modal("Add to the reference archive", `<p class="small muted">The selected images become reference records linked to this approved case.</p><div class="frames">${imgs.map(m => `<label><figure><img src="${esc(m.url)}" alt=""><figcaption><input type="checkbox" value="${esc(m.id)}" ${m.parent ? "" : "checked"}> ${esc(m.id)}</figcaption></figure></label>`).join("")}</div>
      <label class="f" for="at">Title <span class="req">*</span></label><input type="text" id="at" value="${esc(C.title)}"><label class="f" for="ad">What the record shows and how it was established <span class="req">*</span></label><textarea id="ad" rows="3">${esc(`Assessed in case ${C.id} (revision ${C.revision}) as ${CONCL[C.conclusion]?.[0] || "—"}. ${C.conclusion_rationale || ""}`)}</textarea>
      <div class="grid g2"><div><label class="f" for="adt">Documented date</label><input type="date" id="adt" value="${esc((C.published_at || C.received_at).slice(0, 10))}"></div><div><label class="f" for="aty">Record type</label><select id="aty"><option value="misleading" ${["contradicted", "mixed"].includes(C.conclusion) ? "selected" : ""}>Previously documented misleading item</option><option value="original" ${["contradicted", "mixed"].includes(C.conclusion) ? "" : "selected"}>Original with documented origin</option></select></div></div>
      <label class="f" for="ar">Source reference</label><input type="text" id="ar" value="${esc(`Verification report ${C.id} revision ${C.revision}`)}">`,
      [{ label: "Cancel", value: null }, { label: "Add to archive", kind: "primary", validate: async m => { const ids = $$("input[type=checkbox]:checked", m).map(x => x.value); if (!ids.length) return "Choose at least one image."; try { for (const mid of ids) { const md = C.media.find(x => x.id === mid); await Svc.createArchive({ title: $("#at", m).value, description: $("#ad", m).value, documented_date: $("#adt", m).value, record_type: $("#aty", m).value, source_ref: $("#ar", m).value }, { file: await fetchFile(md.url, md.name), assetUrl: md.url, training: C.is_training, fromCase: C.id }); } } catch (e) { return errMsg(e); } }, value: true }], { wide: true });
    if (r.value) act(() => Svc.mutate(C.id, "Media added to the reference archive", () => {}), "Added to the reference archive.");
  }

  // ---------------------------------------------------------------- overview
  function overview(body) {
    const ed = P.edit ? "" : "disabled";
    body.innerHTML = `<div class="split"><div class="stack">
      <div class="card"><div class="hd"><h3>Content as received</h3><span class="chip grey right">Preserved, cannot be edited</span></div><div class="bd"><div class="quote">${esc(C.claim_text_original)}</div></div></div>
      <div class="card"><div class="hd"><h3>Working copy for analysis</h3></div><div class="bd"><textarea id="wc" rows="4" ${ed} aria-label="Working copy">${esc(C.claim_text)}</textarea><div class="hint">Correct obvious transcription errors or translate here. Changes are versioned; the original never changes.</div></div></div>
      <div class="card"><div class="hd"><h3>Source and dates</h3></div><div class="bd">
        <div class="grid g2"><div><label class="f" for="o_t">Title</label><input type="text" id="o_t" value="${esc(C.title)}" ${ed}></div><div><label class="f" for="o_p">Priority</label><select id="o_p" ${ed}>${["routine", "priority", "urgent"].map(p => `<option ${p === C.priority ? "selected" : ""} value="${p}">${p[0].toUpperCase() + p.slice(1)}</option>`).join("")}</select></div></div>
        <div class="grid g3"><div><label class="f" for="o_sp">Where seen</label><input type="text" id="o_sp" value="${esc(C.source_platform)}" ${ed}></div><div><label class="f" for="o_sa">Account</label><input type="text" id="o_sa" value="${esc(C.source_account || "")}" ${ed}></div><div><label class="f" for="o_su">Link / reference</label><input type="text" id="o_su" value="${esc(C.source_url || "")}" ${ed}></div></div>
        <label class="f" for="o_ht">Hashtags</label><input type="text" id="o_ht" value="${esc((C.hashtags || []).join(" "))}" placeholder="#example #another" ${ed}>${(C.hashtags || []).length ? `<div class="row" style="margin-top:6px">${C.hashtags.map(h => `<a class="chip info" href="#/search?q=${encodeURIComponent(h)}" title="Find other records with this hashtag">${esc(h)}</a>`).join("")}</div>` : ""}
        <div class="grid g3"><div><label class="f" for="o_ra">Received</label><input type="datetime-local" id="o_ra" value="${toLocalInput(C.received_at)}" ${ed}></div>
          <div><label class="f" for="o_pa">Published (per source)</label><input type="datetime-local" id="o_pa" value="${toLocalInput(C.published_at)}" ${ed}><input type="text" id="o_pb" value="${esc(C.published_basis || "")}" placeholder="How established" style="margin-top:6px" ${ed}></div>
          <div><label class="f" for="o_ea">Claimed event date</label><input type="datetime-local" id="o_ea" value="${toLocalInput(C.claimed_event_at)}" ${ed}><input type="text" id="o_eb" value="${esc(C.claimed_event_basis || "")}" placeholder="What the content says" style="margin-top:6px" ${ed}></div></div>
        <div class="hint">Capture dates come from each file's metadata and appear on the timeline as leads.</div>${P.edit ? `<div style="margin-top:12px"><button class="btn primary" id="saveO">Save changes</button></div>` : ""}</div></div>
    </div><div class="stack">${timelineCard()}${checklistCard()}</div></div>`;
    if (P.edit) $("#saveO").onclick = () => act(() => Svc.updateCase(C.id, { title: $("#o_t").value.trim(), priority: $("#o_p").value, claim_text: $("#wc").value, source_platform: $("#o_sp").value.trim(), source_account: $("#o_sa").value || null, source_url: $("#o_su").value || null, hashtags: $("#o_ht").value, received_at: fromLocalInput($("#o_ra").value), published_at: fromLocalInput($("#o_pa").value), published_basis: $("#o_pb").value || null, claimed_event_at: fromLocalInput($("#o_ea").value), claimed_event_basis: $("#o_eb").value || null }), "Saved. A new version was recorded.");
    if (P.edit) {
      $$("[data-ck]").forEach(s => s.onchange = () => act(() => Svc.setChecklist(C.id, s.dataset.ck, { state: s.value })));
      $$("[data-ckn]").forEach(i => i.onchange = () => act(() => Svc.setChecklist(C.id, i.dataset.ckn, { note: i.value })));
      $("#ckAdd").onclick = () => { const v = $("#ckNew").value.trim(); if (v) act(() => Svc.setChecklist(C.id, `custom-${Date.now()}`, { label: v }), "Check added."); };
    }
  }
  function timelineCard() {
    const T = [], add = (d, kind, label) => d && !isNaN(new Date(d)) && T.push({ d, kind, label });
    add(C.received_at, "received", `Received by the team (${C.source_platform})`); add(C.published_at, "published", `Published, per source${C.published_basis ? ` — ${C.published_basis}` : ""}`); add(C.claimed_event_at, "claimed", `Event date the content claims${C.claimed_event_basis ? ` — ${C.claimed_event_basis}` : ""}`);
    const ce = extractEntities(C.claim_text); ce.dates.filter(d => d.iso).forEach(d => add(d.iso, "claimed", `Date stated in the post: “${d.text}”`));
    if (ce.relative.length && !C.claimed_event_at) add(C.published_at || C.received_at, "claimed", `Post presents events as current (${ce.relative.map(r => `“${r}”`).join(", ")}) — placed on the ${C.published_at ? "publication" : "received"} date`);
    const seen = new Set(); for (const m of (C.matches || []).filter(x => x.archive_id)) if (!seen.has(m.archive_id)) { seen.add(m.archive_id); add(m.archive_date, "archive", `${m.kind === "exact" ? "Identical file" : m.level === "strong" ? "Strong archive match" : "Possible archive match"}: ${m.archive_id} “${m.archive_title}”`); }
    for (const m of (C.matches || []).filter(x => x.case_id)) add(m.case_received_at, "case", `Same media received in case ${m.case_id}`);
    for (const m of C.media.filter(x => x.meta_capture_at)) add(m.meta_capture_at, "meta", `Capture time in metadata of ${m.id} (lead; time zone unknown)`);
    for (const o of C.ocr) extractEntities(o.current_text).dates.filter(d => d.iso).forEach(d => add(d.iso, "visible", `Date visible in ${o.media_id}: “${d.text}”`));
    T.sort((a, b) => new Date(a.d) - new Date(b.d));
    const claimed = T.filter(t => ["claimed", "published"].includes(t.kind)).map(t => +new Date(t.d)), ev = T.filter(t => ["archive", "visible", "meta"].includes(t.kind));
    let conflict = null; if (claimed.length && ev.length) { const gap = (Math.min(...claimed) - new Date(ev[0].d)) / 864e5; if (gap > 30) conflict = { e: ev[0], days: Math.round(gap) }; }
    const L = { received: "Received", published: "Published", claimed: "Claimed", archive: "Archive", case: "Other case", meta: "Metadata", visible: "Visible text" }, span = d => d >= 730 ? `${Math.round(d / 365)} years` : d >= 60 ? `${Math.round(d / 30)} months` : `${d} days`;
    return `<div class="card"><div class="hd"><h3>Date timeline</h3><span class="small sub right">Each date as one source states it</span></div><div class="bd">${conflict ? `<div class="callout bad" style="margin-bottom:10px"><div><b>Timing conflict.</b> ${esc(conflict.e.label)} (${fmtD(conflict.e.d)}) is ${span(conflict.days)} earlier than the timing the content claims. Treat this as a lead and confirm the earlier date independently.</div></div>` : ""}
      ${T.length ? `<ol class="tl">${T.map(t => `<li class="${t.kind}"><span class="num small">${fmtD(t.d)}</span><span><span class="chip grey">${L[t.kind]}</span></span><span class="small">${esc(t.label)}</span></li>`).join("")}</ol>` : `<p class="muted small">No dates recorded yet.</p>`}</div></div>`;
  }
  function checklistCard() {
    const done = C.checklist.filter(k => k.state !== "todo").length, ed = P.edit ? "" : "disabled";
    return `<div class="card"><div class="hd"><h3>Verification checklist</h3><span class="chip ${done === C.checklist.length ? "sup" : "grey"} right">${done} of ${C.checklist.length} addressed</span></div><div class="bd"><div class="ckl">${C.checklist.map(k => `<div class="it ${k.state}"><select data-ck="${esc(k.step)}" ${ed} aria-label="${esc(k.label)}"><option value="todo">Not done</option><option value="done" ${k.state === "done" ? "selected" : ""}>Done</option><option value="na" ${k.state === "na" ? "selected" : ""}>Not applicable</option></select><span>${esc(k.label)}</span><input type="text" data-ckn="${esc(k.step)}" value="${esc(k.note || "")}" placeholder="Note or reference" ${ed}></div>`).join("")}</div>
      ${P.edit ? `<div class="row" style="margin-top:10px"><input type="text" id="ckNew" placeholder="Add a case-specific check" style="max-width:360px"><button class="btn sm" id="ckAdd">Add</button></div>` : ""}</div></div>`;
  }

  // ---------------------------------------------------------------- media
  function media(body) {
    const top = C.media.filter(m => !m.parent), frames = id => C.media.filter(m => m.parent === id);
    body.innerHTML = `${P.edit && PL.assets ? `<div class="card"><div class="bd"><div class="dropzone" id="dz" tabindex="0" role="button"><b>Add images or video</b><div class="small muted">Drop files, paste a screenshot (Ctrl+V) or choose files (up to 20 MB). Re-run checks afterwards to compare new media.</div><input type="file" id="fi" multiple accept="image/*,video/*" hidden></div><ul class="uplist" id="ul"></ul></div></div>` : ""}
      <div class="card"><div class="hd"><h3>Media under examination</h3><span class="small sub right">${C.media.length} item(s) · archive similarity and metadata are investigative leads, not proof</span></div>
      ${top.length ? top.map(m => m.kind === "video" ? videoCard(m, frames(m.id)) + frames(m.id).map(imageCard).join("") : imageCard(m)).join("") : `<div class="bd">${empty("No media attached", "This case has text only. Add the image or video that circulated with the post, if there was one.")}</div>`}</div>`;
    if (P.edit && PL.assets) bindDrop($("#dz"), $("#fi"), async files => { for (const f of files) { const li = document.createElement("li"); li.innerHTML = `<div class="ph">${f.type.startsWith("video") ? "VIDEO" : "IMG"}</div><div><b class="small">${esc(f.name)}</b><div class="tiny sub st">Fingerprinting and uploading…</div></div><span></span>`; $("#ul").appendChild(li); try { const m = await Svc.addMedia(C.id, f); li.querySelector(".st").textContent = `Stored as ${m.id}.`; } catch (e) { li.querySelector(".st").textContent = errMsg(e); li.querySelector(".st").style.color = "var(--con)"; } } toast("Upload finished. Re-run checks to compare the new media."); reload(); });
    bindMedia();
  }
  const explain = x => x.kind === "exact" ? "The two files are byte-for-byte identical (equal SHA-256). This shows the same file was received before; it says nothing about where it originally came from."
    : `${x.dd} of 64 gradient bits and ${x.pd} of 64 frequency bits differ (${x.score} of 128 in total; lower means more alike). In the built-in test set, re-saved, cropped, recoloured or captioned copies scored 18 or less and unrelated pictures 45 or more. This measures how alike the two files look — it is not a probability that they show the same event.`;
  function imageCard(m) {
    const ms = (C.matches || []).filter(x => x.media_id === m.id), ocr = C.ocr.filter(o => o.media_id === m.id), meta = Object.entries(m.meta || {});
    return `<div class="mediacard" id="mc-${esc(m.id)}"><div><div class="pv"><img src="${esc(m.url)}" alt="${esc(m.name)}" data-view="${esc(m.id)}" loading="lazy"></div>
      <div class="row" style="margin-top:8px"><button class="btn sm" data-view="${esc(m.id)}">Enlarge</button><button class="btn sm adv" data-ela="${esc(m.id)}">Error level analysis</button><button class="btn sm" data-web="${esc(m.id)}">Search the web</button></div><div data-elabox="${esc(m.id)}" hidden></div></div>
      <div style="min-width:0"><h4>${esc(m.id)} ${m.parent ? `<span class="chip info">Frame at ${m.frame_time.toFixed(2)} s of ${esc(m.parent)} · ${m.frame_origin === "auto" ? "auto-sampled" : "selected by analyst"}</span>` : `<span class="small sub" style="font-weight:400">${esc(m.name)}</span>`}</h4>
        <dl class="kv" style="margin-top:8px"><dt>File</dt><dd>${esc(m.mime)} · ${kb(m.size)}${m.width ? ` · ${m.width}×${m.height}` : ""} · received ${fmtDT(m.uploaded_at)}</dd><dt>SHA-256 (exact bytes)</dt><dd class="mono tiny">${esc(m.sha256)}</dd><dt class="adv">Perceptual hashes</dt><dd class="mono tiny adv">dHash ${esc(m.dhash || "—")} · pHash ${esc(m.phash || "—")}</dd>
          <dt>Embedded metadata</dt><dd>${meta.length ? meta.map(([k, v]) => `<div><span class="sub">${esc(k)}:</span> ${esc(v)}</div>`).join("") : `<span class="sub">None found${m.mime !== "image/jpeg" ? " (this version reads JPEG metadata only)" : ""}. Nothing follows from its absence.</span>`}<div class="tiny sub">Investigative lead only: metadata can be edited, copied or stripped.</div></dd></dl>
        <div style="margin-top:12px"><b class="small">Matches</b>${ms.length ? ms.map(x => matchBlock(m, x)).join("") : `<div class="callout info" style="margin-top:6px"><div>${C.status === "draft" ? "Run local analysis to search the reference archive." : "No earlier copy in the reference archive or other cases. This does not show the image is new, original or authentic."}</div></div>`}</div>
        <div class="ocrbox"><div class="row"><b class="small">Visible text</b>${P.edit ? `<span style="margin-left:auto" class="row">${LOCALOCR ? `<select data-ocrlang="${esc(m.id)}" aria-label="Language of the text" style="width:auto;padding:4px 6px;font-size:12.5px"><option value="eng">English</option><option value="swa">Kiswahili</option><option value="eng+swa">English + Kiswahili</option></select><button class="btn sm primary" data-ocr="${esc(m.id)}">Read text (offline)</button>` : ""}<button class="btn sm" data-type="${esc(m.id)}">Type it in</button>${PL.sample && can("ai.request") ? `<button class="btn sm" data-aiocr="${esc(m.id)}">Transcribe with Claude</button>` : ""}</span>` : ""}</div>
          ${ocr.map(o => `<div style="margin-top:10px"><div class="tiny sub">${esc(o.engine)} · ${fmtDT(o.created_at)}${o.versions.length ? ` · ${o.versions.length} correction(s)` : ""}</div><textarea data-ocrtext="${esc(o.id)}" rows="4" ${P.edit ? "" : "disabled"} aria-label="Checked text">${esc(o.current_text)}</textarea>
            <div class="row" style="margin-top:4px">${P.edit ? `<button class="btn sm" data-ocrsave="${esc(o.id)}">Save correction</button>` : ""}<details><summary class="tiny sub">First transcription (unchanged)</summary><pre class="box">${esc(o.original_text)}</pre></details></div></div>`).join("") || `<div class="hint">No visible text recorded. ${LOCALOCR ? "Read it with the offline text reader (nothing leaves this computer), or type what you can read." : "Type what you can read, or ask Claude to transcribe it (sends this image after you confirm)."}</div>`}</div></div></div>`;
  }
  function matchBlock(m, x) {
    const lvl = x.kind === "exact" ? `<span class="chip con">Identical file</span>` : x.level === "strong" ? `<span class="chip con">Strong similarity</span>` : `<span class="chip warn">Possible similarity</span>`;
    const target = x.archive_id ? `Archive <b>${esc(x.archive_id)}</b> · ${esc(x.archive_title)} · documented ${fmtD(x.archive_date)} ${x.archive_type === "misleading" ? `<span class="chip con">previously assessed misleading</span>` : `<span class="chip sup">documented original</span>`}` : `Case <a href="#/case/${esc(x.case_id)}">${esc(x.case_id)}</a> · ${esc(x.case_title)} · ${esc(STATUS[x.case_status])}`;
    const modes = ["Side by side", "Slider", ...(x.kind === "exact" ? [] : ["Differences"]), ...(x.archive_id && x.ww != null ? ["Matched region"] : [])];
    return `<div class="match ${x.kind === "exact" ? "identical" : x.level}"><div class="mh">${lvl}<span class="small" style="min-width:0">${target}</span></div><div class="mb">${x.archive_id ? `<div class="small muted">${esc(x.archive_description || "")} <span class="sub">Source: ${esc(x.archive_ref || "")}</span></div>` : ""}
      <div class="explain">${explain(x)}${x.kind !== "exact" ? ` Best match on the reference's <b>${esc(x.window)}</b>${x.mirrored ? "; the submission is a <b>mirror image</b>" : ""}.` : ""}</div>
      ${!x.target_url ? `<div class="callout info" style="margin-top:8px"><div>The matched ${x.archive_id ? "archive image" : "case file"} is not held here (this case was imported from another AIVS). ${x.archive_id ? "Import the sender's archive bundle, then re-run the checks, to compare the images." : ""}</div></div>` : `<div class="seg" style="margin-top:8px" role="group">${modes.map((l, i) => `<button class="${i === 0 ? "on" : ""}" data-cmp="${esc(x.id)}" data-mode="${l}">${l}</button>`).join("")}</div><div data-cmpbox="${esc(x.id)}">${sbs(m, x)}</div>`}</div></div>`;
  }
  const sbs = (m, x) => `<div class="compare sbs"><figure><img src="${esc(m.url)}" alt="Submitted" style="${x.mirrored ? "transform:scaleX(-1)" : ""}"><figcaption>Submitted ${esc(m.id)}${x.mirrored ? " (flipped back)" : ""}</figcaption></figure><figure><img src="${esc(x.target_url)}" alt="Reference"><figcaption>${x.archive_id ? `Archive ${esc(x.archive_id)}` : `Case ${esc(x.case_id)}`}</figcaption></figure></div>`;
  function videoCard(m, frames) {
    return `<div class="mediacard"><div><div class="pv"><video id="vid-${esc(m.id)}" src="${esc(m.url)}" controls preload="metadata" crossorigin="anonymous"></video></div>
      <div class="row" style="margin-top:8px">${P.edit ? `<button class="btn sm primary" data-cap="${esc(m.id)}">Capture this frame</button><button class="btn sm" data-sample="${esc(m.id)}">Sample 6 frames</button>` : ""}</div><div class="tiny sub" id="vt-${esc(m.id)}" style="margin-top:4px"></div></div>
      <div><h4>${esc(m.id)} <span class="small sub" style="font-weight:400">${esc(m.name)}</span> <span class="chip grey">Video</span></h4><dl class="kv" style="margin-top:8px"><dt>File</dt><dd>${esc(m.mime)} · ${kb(m.size)} · received ${fmtDT(m.uploaded_at)}</dd><dt>SHA-256 (exact bytes)</dt><dd class="mono tiny">${esc(m.sha256)}</dd></dl>
      <p class="small muted">Video is compared through its frames. Pause on a moment worth checking and capture it; the timestamp is recorded with the frame. Re-run checks to compare captured frames.</p>
      <div class="frames">${frames.map(f => `<figure><img src="${esc(f.url)}" alt=""><figcaption class="num">${f.frame_time.toFixed(2)} s · ${f.frame_origin === "auto" ? "auto" : "analyst"}${(C.matches || []).some(x => x.media_id === f.id && x.level !== "possible") ? ` <span class="chip con">match</span>` : ""}</figcaption></figure>`).join("") || `<span class="small sub">No frames yet.</span>`}</div></div></div>`;
  }
  function bindMedia() {
    $$("[data-view]").forEach(b => b.onclick = () => { const m = C.media.find(x => x.id === b.dataset.view); viewer(m.url, `${m.id} · ${m.name}`); });
    $$("[data-ela]").forEach(b => b.onclick = async () => { const box = $(`[data-elabox="${b.dataset.ela}"]`); if (!box.hidden) { box.hidden = true; return; } b.innerHTML = '<span class="spin"></span> Computing…';
      try { const r = await errorLevel(C.media.find(x => x.id === b.dataset.ela).url); box.innerHTML = `<img src="${r.url}" alt="Error level analysis" style="width:100%;margin-top:8px;border-radius:6px;cursor:zoom-in"><div class="hint">Bright areas recompress differently. Edges, text and re-saved images are naturally bright. Use it to decide where to look closer; it does not prove editing or AI generation.</div>`; box.hidden = false; box.querySelector("img").onclick = () => viewer(r.url, "Error level analysis"); } catch (e) { fail(e); } b.textContent = "Error level analysis"; });
    $$("[data-cmp]").forEach(b => b.onclick = async () => {
      const x = C.matches.find(y => y.id === b.dataset.cmp), m = C.media.find(y => y.id === x.media_id), box = $(`[data-cmpbox="${CSS.escape(x.id)}"]`); b.parentElement.querySelectorAll("button").forEach(y => y.classList.toggle("on", y === b));
      const mode = b.dataset.mode;
      if (mode === "Side by side") box.innerHTML = sbs(m, x);
      if (mode === "Slider") { box.innerHTML = `<div class="compare slider"><img src="${esc(x.target_url)}" alt=""><div class="clip"><img src="${esc(m.url)}" alt="" style="${x.mirrored ? "transform:scaleX(-1)" : ""}"></div><span class="lbl">Submitted</span><span class="lbl r">Reference</span></div><div class="hint">Drag across the image, or focus it and use the arrow keys.</div>`; bindSlider(box.querySelector(".slider")); }
      if (mode === "Differences") { box.innerHTML = `<div class="small muted" style="padding:10px"><span class="spin"></span> Aligning and comparing…</div>`; try { const r = await differenceMap(x.target_url, m.url, !!x.mirrored, x.ww); box.innerHTML = `<div class="compare"><img class="single" src="${r.url}" alt="Difference map"></div><div class="explain"><b>${Math.round(r.changed * 100)}%</b> of the submitted image differs noticeably from the reference (red). Aligned to ${Math.round(r.region.w * 100)}% × ${Math.round(r.region.h * 100)}% of the reference. Red marks added, removed or altered content such as a caption banner or crop edge; scattered specks are compression noise. It does not show who changed what, or when.</div>`; box.querySelector("img").onclick = () => viewer(r.url, "Difference map"); } catch (e) { box.innerHTML = `<div class="callout bad"><div>${esc(errMsg(e))}</div></div>`; } }
      if (mode === "Matched region") { const u = await matchedRegion(x.target_url, { wx: x.wx, wy: x.wy, ww: x.ww, wh: x.wh }); box.innerHTML = `<div class="compare"><img class="single" src="${u}" alt="Matched region"></div><div class="explain">The outlined area of archive ${esc(x.archive_id)} is the part that best matches the submission (${esc(x.window)}).</div>`; }
    });
    $$("[data-web]").forEach(b => b.onclick = () => webSearch(C.media.find(x => x.id === b.dataset.web)));
    $$("[data-ocr]").forEach(b => b.onclick = async () => {
      const m = C.media.find(x => x.id === b.dataset.ocr), lang = $(`[data-ocrlang="${CSS.escape(m.id)}"]`).value;
      b.disabled = true; b.innerHTML = '<span class="spin"></span> Starting the text reader…';
      try {
        const r = await LOCALOCR.read(m.url, lang, p => { b.textContent = `Reading… ${Math.round(p * 100)}%`; });
        if (!r.text) { toast("No readable text was found in this image.", ""); b.disabled = false; b.textContent = "Read text (offline)"; return; }
        await Svc.addOcr(C.id, m.id, { engine: r.engine, lang, text: r.text, confidence: r.confidence });
        toast(`Text read (confidence ${Math.round(r.confidence)}%). Check it against the image and correct it; the first reading is kept.`); await reload();
      } catch (e) { fail(e); b.disabled = false; b.textContent = "Read text (offline)"; }
    });
    $$("[data-type]").forEach(b => b.onclick = async () => { const r = await modal("Type the visible text", `<p class="small muted">Copy the text exactly as it appears, including spelling mistakes and dates.</p><textarea id="tt" rows="8"></textarea>`, [{ label: "Cancel", value: null }, { label: "Save", kind: "primary", value: m => $("#tt", m).value }]); if (r.value?.trim()) act(() => Svc.addOcr(C.id, b.dataset.type, { engine: "Manual transcription", lang: "as written", text: r.value }), "Text recorded."); });
    $$("[data-aiocr]").forEach(b => b.onclick = async () => {
      const m = C.media.find(x => x.id === b.dataset.aiocr);
      if (!(await confirmBox("Send this image to Claude?", `Image ${m.id} will be sent to Claude (Anthropic) through claude.ai on your account, to transcribe its visible text. The request is recorded in the case audit trail.`, "Send"))) return;
      b.disabled = true; b.innerHTML = '<span class="spin"></span> Transcribing…';
      try { await Svc.mutate(C.id, `Image ${m.id} sent to Claude for transcription`, () => {}); const r = await transcribeWithAI(C, m); await Svc.addOcr(C.id, m.id, { engine: `AI transcription (${r.model}) — check by eye`, lang: "auto", text: r.text }); toast("Text transcribed. Check it against the image and correct it if needed."); } catch (e) { fail(e.code === "not_granted" ? new AppError("AI assistance was not allowed for this page.") : e); }
      reload();
    });
    $$("[data-ocrsave]").forEach(b => b.onclick = () => act(() => Svc.editOcr(C.id, b.dataset.ocrsave, $(`[data-ocrtext="${CSS.escape(b.dataset.ocrsave)}"]`).value), "Correction saved. The first transcription is kept."));
    $$("[data-cap]").forEach(b => b.onclick = async () => { const v = $(`#vid-${CSS.escape(b.dataset.cap)}`); if (!v.videoWidth) return toast("Play or seek the video first so a frame is loaded.", "err"); v.pause(); const t = v.currentTime; b.disabled = true;
      try { const blob = await frameBlob(v), src = C.media.find(x => x.id === b.dataset.cap); await Svc.addMedia(C.id, new File([blob], `${src.name} @ ${t.toFixed(2)}s.png`, { type: "image/png" }), { parent: src.id, frameTime: t, frameOrigin: "analyst" }); toast(`Frame at ${t.toFixed(2)} s captured. Re-run checks to compare it.`); } catch (e) { fail(e); } reload(); });
    $$("[data-sample]").forEach(b => b.onclick = async () => { b.disabled = true; const st = $(`#vt-${CSS.escape(b.dataset.sample)}`); try { const n = await sampleFrames(C.id, C.media.find(x => x.id === b.dataset.sample), 6, p => (st.textContent = `Extracting frames… ${Math.round(p * 100)}%`)); toast(`${n} frames extracted.`); } catch (e) { st.textContent = errMsg(e); } reload(); });
    $$("video").forEach(v => { const st = $(`#vt-${CSS.escape(v.id.slice(4))}`); v.ontimeupdate = () => st && (st.textContent = `Position ${v.currentTime.toFixed(2)} s of ${isFinite(v.duration) ? v.duration.toFixed(2) : "?"} s`); v.onerror = () => st && (st.innerHTML = `<span style="color:var(--con)">This browser cannot play this video format. Convert it to MP4 (H.264) and add the converted copy.</span>`); });
  }

  // ---------------------------------------------------------------- claims
  function claims(body) {
    const active = C.claims.filter(x => !x.removed), removed = C.claims.filter(x => x.removed), ed = P.edit, exp = expectedConclusion(C.claims), n = k => active.filter(x => x.assessment === k).length;
    const linked = cl => C.evidence.filter(e => e.status === "accepted" && (e.links || []).some(l => l.claim_id === cl.id)).map(e => ({ e, s: e.links.find(l => l.claim_id === cl.id).stance }));
    body.innerHTML = `<div class="card"><div class="bd"><div class="row" style="gap:18px"><div><div class="label">Assessed</div><div class="num" style="font-size:20px;font-weight:800">${active.length - n("unassessed")} / ${active.length}</div></div>${["supported", "contradicted", "insufficient"].map(k => `<div><div class="label">${ASSESS[k][0]}</div><div class="num" style="font-size:20px;font-weight:800;color:var(--${ASSESS[k][1]})">${n(k)}</div></div>`).join("")}
      <div style="margin-left:auto;max-width:440px" class="small">${exp ? `These assessments lead to an overall conclusion of ${concl(exp)}.${exp === "mixed" ? " The post contains both supported and contradicted claims." : ""}` : `Assess every claim to reach an overall conclusion. A post with both supported and contradicted claims is concluded as <b>Mixed findings</b>.`}</div></div></div></div>
      ${!active.length ? `<div class="card"><div class="bd">${empty(C.status === "draft" ? "Claims appear after analysis" : "No claims", C.status === "draft" ? "Run local analysis to split the post into checkable claims, or add claims yourself." : "Add the specific, checkable statements the content makes.")}</div></div>` : ""}
      <div style="margin-top:14px">${active.map(cl => { const L = linked(cl); return `<div class="claim a-${cl.assessment}"><div class="no">${cl.seq}</div><div style="min-width:0">
        <div class="row" style="margin-bottom:6px"><span class="chip grey">${esc(cl.kind)}</span>${cl.claim_type && cl.claim_type !== "factual" ? `<span class="chip warn" title="Rule-based hint${cl.claim_type_cue ? `: triggered by “${esc(cl.claim_type_cue)}”` : ""}. You decide.">${esc(STYPE[cl.claim_type] || cl.claim_type)}</span>` : cl.claim_type === "factual" ? `<span class="chip teal adv" title="Rule-based hint">checkable statement</span>` : ""}<span class="chip ${cl.origin === "ai" ? "info" : cl.origin === "extracted" ? "teal" : "grey"}">${cl.origin === "ai" ? "suggested by AI" : cl.origin === "extracted" ? "extracted automatically" : "added by analyst"}</span>${ed ? `<span style="margin-left:auto" class="row"><select data-ckind="${cl.id}" style="width:auto;padding:3px 6px;font-size:12.5px" aria-label="Claim type">${["statement", "timing", "media", "location", "attribution"].map(k => `<option ${k === cl.kind ? "selected" : ""}>${k}</option>`).join("")}</select><button class="btn sm ghost" data-split="${cl.id}">Split</button><button class="btn sm ghost" data-rm="${cl.id}">Remove</button></span>` : ""}</div>
        ${cl.claim_type && cl.claim_type !== "factual" ? `<div class="hint" style="margin:-2px 0 6px">${esc(STYPE_HELP[cl.claim_type] || "")}</div>` : ""}<textarea class="ct" data-ctext="${cl.id}" rows="2" ${ed ? "" : "disabled"} aria-label="Claim ${cl.seq}">${esc(cl.text)}</textarea>
        <div class="row" style="margin-top:8px"><div class="seg" role="group" aria-label="Assessment">${["supported", "contradicted", "insufficient", "unassessed"].map(k => `<button data-v="${k}" data-assess="${cl.id}" class="${cl.assessment === k ? "on" : ""}" ${ed ? "" : "disabled"}>${ASSESS[k][0]}</button>`).join("")}</div>${cl.assessed_by ? `<span class="tiny sub">by ${esc(N(cl.assessed_by))} ${ago(cl.assessed_at)}</span>` : ""}</div>
        <label class="f" for="r-${cl.id}">Rationale for this claim</label><textarea id="r-${cl.id}" data-rat="${cl.id}" rows="2" ${ed ? "" : "disabled"} placeholder="What the evidence shows for this claim, and what it does not">${esc(cl.rationale || "")}</textarea>
        <div class="links">${L.map(({ e, s }) => `<span class="chip ${s === "supports" ? "sup" : s === "contradicts" ? "con" : "grey"}" title="${esc(e.text)}">${esc(e.id)} ${s}</span>`).join("") || `<span class="tiny sub">No evidence linked.</span>`}${ed ? `<button class="btn sm ghost" data-link="${cl.id}">Link evidence</button>` : ""}</div></div></div>`; }).join("")}</div>
      ${ed ? `<div class="card" style="margin-top:14px"><div class="bd"><label class="f" for="nc" style="margin-top:0">Add a claim</label><div class="row"><input type="text" id="nc" placeholder="One specific, checkable statement" style="flex:1;min-width:240px"><select id="nck" style="width:auto">${["statement", "timing", "media", "location", "attribution"].map(k => `<option>${k}</option>`).join("")}</select><button class="btn primary" id="ncAdd">Add claim</button></div></div></div>` : ""}
      ${removed.length ? `<details style="margin-top:14px"><summary class="small sub">Removed or split claims (${removed.length}) — kept for the record</summary>${removed.map(cl => `<div class="panel small" style="margin-top:6px"><s>${esc(cl.text)}</s></div>`).join("")}</details>` : ""}`;
    if (!ed) return;
    $$("[data-assess]").forEach(b => b.onclick = () => act(() => Svc.updateClaim(C.id, b.dataset.assess, { assessment: b.dataset.v, rationale: $(`[data-rat="${b.dataset.assess}"]`).value })));
    $$("[data-rat]").forEach(t => t.onchange = () => act(() => Svc.updateClaim(C.id, t.dataset.rat, { rationale: t.value })));
    $$("[data-ctext]").forEach(t => t.onchange = () => act(() => Svc.updateClaim(C.id, t.dataset.ctext, { text: t.value }), "Claim updated."));
    $$("[data-ckind]").forEach(s => s.onchange = () => act(() => Svc.updateClaim(C.id, s.dataset.ckind, { kind: s.value })));
    $$("[data-split]").forEach(b => b.onclick = async () => { const cl = C.claims.find(x => x.id === b.dataset.split); const r = await modal("Split claim", `<p class="small muted">Put each separate statement on its own line, or leave it to split automatically.</p><textarea id="sp" rows="5">${esc(cl.text)}</textarea>`, [{ label: "Cancel", value: null }, { label: "Split", kind: "primary", value: m => $("#sp", m).value }]); if (r.value != null) act(() => Svc.splitClaim(C.id, cl.id, r.value.split(/\n+/).map(s => s.trim()).filter(Boolean)), "Claim split."); });
    $$("[data-rm]").forEach(b => b.onclick = async () => { if (await confirmBox("Remove this claim?", "It stays in the record as removed, with its evidence links cleared.", "Remove", "danger")) act(() => Svc.removeClaim(C.id, b.dataset.rm), "Claim removed."); });
    $$("[data-link]").forEach(b => b.onclick = async () => {
      const cid = b.dataset.link, acc = C.evidence.filter(e => e.status === "accepted"); if (!acc.length) return toast("Accept or add evidence first (Evidence tab).", "err");
      const cur = e => (e.links || []).find(l => l.claim_id === cid)?.stance || "";
      const r = await modal("Link evidence to this claim", `<p class="small muted">Choose how each accepted item bears on the claim.</p>${acc.map(e => `<div class="ev k-${e.kind}" style="display:grid;grid-template-columns:minmax(0,1fr) 150px;gap:10px;align-items:center"><div class="small"><b class="mono">${esc(e.id)}</b> <span class="chip grey">${KIND[e.kind][0]}</span> ${esc(e.text)}</div><select data-st="${esc(e.id)}"><option value="">Not related</option>${["supports", "contradicts", "context"].map(s => `<option value="${s}" ${cur(e) === s ? "selected" : ""}>${s === "context" ? "Context only" : s[0].toUpperCase() + s.slice(1)}</option>`).join("")}</select></div>`).join("")}`, [{ label: "Cancel", value: null }, { label: "Save links", kind: "primary", value: m => $$("[data-st]", m).map(s => ({ id: s.dataset.st, stance: s.value })) }], { wide: true });
      if (r.value) act(() => Svc.mutate(C.id, "Evidence links edited", c => { requireEdit(c); for (const { id: eid, stance } of r.value) { const e = c.evidence.find(x => x.id === eid); e.links = (e.links || []).filter(l => l.claim_id !== cid).concat(stance ? [{ claim_id: cid, stance }] : []); } }), "Links saved.");
    });
    $("#ncAdd").onclick = () => { const t = $("#nc").value.trim(); if (!t) return toast("Write the claim first.", "err"); act(() => Svc.addClaim(C.id, { text: t, kind: $("#nck").value }), "Claim added."); };
  }

  // ---------------------------------------------------------------- evidence
  function evidence(body) {
    const ed = P.edit, active = C.claims.filter(x => !x.removed), sug = C.evidence.filter(e => e.status === "suggested"), acc = C.evidence.filter(e => e.status === "accepted"), dis = C.evidence.filter(e => e.status === "dismissed");
    const origin = e => e.origin === "system" ? "System lead" : e.origin === "ai" ? "AI suggestion" : "Analyst";
    const linkEd = e => active.length ? `<div class="grid" style="grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:6px;margin-top:8px">${active.map(cl => { const s = (e.status === "suggested" ? e.suggested_links || [] : e.links || []).find(l => l.claim_id === cl.id)?.stance || ""; return `<label class="small" style="display:grid;grid-template-columns:auto 1fr;gap:6px;align-items:center"><span class="chip grey">Claim ${cl.seq}</span><select data-ln="${esc(e.id)}" data-cl="${cl.id}" style="padding:3px 6px;font-size:12.5px" ${ed ? "" : "disabled"} title="${esc(cl.text)}"><option value="">Not related</option>${["supports", "contradicts", "context"].map(x => `<option value="${x}" ${s === x ? "selected" : ""}>${x === "context" ? "Context" : x[0].toUpperCase() + x.slice(1)}</option>`).join("")}</select></label>`; }).join("")}</div>` : "";
    const item = e => `<div class="ev k-${e.kind} ${e.status === "suggested" ? "sugg" : ""}"><div class="row"><span class="mono small"><b>${esc(e.id)}</b></span><span class="chip grey">${KIND[e.kind][0]}</span><span class="chip ${e.origin === "ai" ? "info" : e.origin === "system" ? "teal" : "grey"}">${origin(e)}</span>${e.media_id ? `<span class="small mono">${esc(e.media_id)}</span>` : ""}${e.uncertainty ? `<span class="chip warn">${esc(e.uncertainty)}</span>` : ""}</div>
      <div style="margin-top:6px">${esc(e.text)}</div><div class="meta"><span>Reference: ${esc(e.reference)}</span>${e.source_date ? `<span>· Source dated <b>${esc(e.source_date)}</b></span>` : `<span class="sub">· Source date not recorded</span>`}${e.decided_by ? `<span>· ${e.status} by ${esc(N(e.decided_by))} ${ago(e.decided_at)}</span>` : ""}</div>
      ${e.versions?.length ? `<details class="small" style="margin-top:6px"><summary class="sub">Corrected ${e.versions.length} time${e.versions.length > 1 ? "s" : ""} — earlier wording kept</summary>${e.versions.slice().reverse().map(v => `<div class="ev-old"><div class="tiny sub">Replaced ${fmtDT(v.replaced_at)} by ${esc(N(v.replaced_by))}</div><div>${esc(v.text)}</div><div class="tiny sub">Reference: ${esc(v.reference)}${v.source_date ? ` · source dated ${esc(v.source_date)}` : ""}</div></div>`).join("")}</details>` : ""}${e.status !== "dismissed" ? linkEd(e) : ""}
      ${ed ? `<div class="row" style="margin-top:8px">${e.status === "suggested" ? `<button class="btn sm primary" data-acc="${esc(e.id)}">Accept</button><button class="btn sm" data-dis="${esc(e.id)}">Dismiss</button>` : e.status === "accepted" ? `<button class="btn sm" data-savel="${esc(e.id)}">Save links</button><button class="btn sm" data-fix="${esc(e.id)}">${e.origin === "analyst" ? "Correct" : "Set source date"}</button><button class="btn sm ghost" data-wd="${esc(e.id)}">Withdraw</button>` : `<button class="btn sm ghost" data-rs="${esc(e.id)}">Restore as suggestion</button>`}</div>` : ""}</div>`;
    body.innerHTML = `<div class="kindlegend">${Object.entries(KIND).map(([k, [l, d]]) => `<div class="k-${k}"><b>${l}</b>${d}</div>`).join("")}</div>
      ${sug.length ? `<div class="card"><div class="hd"><h3>Suggestions to review</h3><span class="chip warn">${sug.length}</span><span class="small sub right">Nothing counts until you accept it. Set how each item bears on the claims first.</span></div><div class="bd">${sug.map(item).join("")}</div></div>` : ""}
      <div class="card"><div class="hd"><h3>Accepted evidence</h3><span class="chip teal">${acc.length}</span></div><div class="bd">${acc.length ? Object.keys(KIND).map(k => { const it = acc.filter(e => e.kind === k); return it.length ? `<h4 style="margin:10px 0 6px">${KIND[k][0]}s</h4>${it.map(item).join("")}` : ""; }).join("") : `<p class="muted small">No evidence accepted yet.</p>`}</div></div>
      ${ed ? `<div class="card"><div class="hd"><h3>Add evidence</h3></div><div class="bd"><div class="grid g3"><div><label class="f" for="nk">Type <span class="req">*</span></label><select id="nk">${Object.entries(KIND).map(([k, [l]]) => `<option value="${k}">${l}</option>`).join("")}</select><div class="hint" id="nkh">${KIND.observation[1]}</div></div>
        <div><label class="f" for="nm">Relates to media</label><select id="nm"><option value="">None</option>${C.media.map(m => `<option value="${esc(m.id)}">${esc(m.id)} · ${esc(m.name)}</option>`).join("")}</select></div><div><label class="f" for="nu">Uncertainty</label><input type="text" id="nu" placeholder="Optional, e.g. single source"></div></div>
        <label class="f" for="nt">Finding <span class="req">*</span></label><textarea id="nt" rows="3" placeholder="State it factually. Keep inference separate from what was observed."></textarea><div class="grid" style="grid-template-columns:minmax(0,1fr) minmax(0,200px);gap:12px"><div><label class="f" for="nr">Reference <span class="req">*</span></label><input type="text" id="nr" placeholder="Document, URL, message ID, person and date, or media ID"></div><div><label class="f" for="nsd">Source date</label><input type="text" id="nsd" placeholder="2018-10-14" inputmode="numeric"><div class="hint">Date the source itself carries: year, year-month or full date.</div></div></div>
        ${active.length ? `<label class="f">How it bears on the claims</label>${linkEd({ id: "new", status: "accepted", links: [] })}` : ""}<div id="evErr" class="callout bad" style="margin-top:10px" hidden></div><div style="margin-top:12px"><button class="btn primary" id="addEv">Add evidence</button></div></div></div>` : ""}
      ${dis.length ? `<details style="margin-top:14px"><summary class="small sub">Dismissed suggestions (${dis.length})</summary><div style="margin-top:8px">${dis.map(item).join("")}</div></details>` : ""}`;
    if (!ed) return;
    const linksOf = id => $$(`[data-ln="${CSS.escape(id)}"]`).filter(s => s.value).map(s => ({ claim_id: s.dataset.cl, stance: s.value }));
    $("#nk").onchange = e => ($("#nkh").textContent = KIND[e.target.value][1]);
    $$("[data-acc]").forEach(b => b.onclick = () => act(() => Svc.updateEvidence(C.id, b.dataset.acc, { status: "accepted", links: linksOf(b.dataset.acc) }), `${b.dataset.acc} accepted.`));
    $$("[data-dis]").forEach(b => b.onclick = () => act(() => Svc.updateEvidence(C.id, b.dataset.dis, { status: "dismissed" }), `${b.dataset.dis} dismissed.`));
    $$("[data-savel]").forEach(b => b.onclick = () => act(() => Svc.updateEvidence(C.id, b.dataset.savel, { links: linksOf(b.dataset.savel) }), "Links saved."));
    $$("[data-wd]").forEach(b => b.onclick = () => act(() => Svc.updateEvidence(C.id, b.dataset.wd, { status: "suggested" }), "Moved back to suggestions."));
    $$("[data-rs]").forEach(b => b.onclick = () => act(() => Svc.updateEvidence(C.id, b.dataset.rs, { status: "suggested" }), "Restored."));
    $$("[data-fix]").forEach(b => b.onclick = () => correctEvidence(C.evidence.find(e => e.id === b.dataset.fix)));
    $("#addEv").onclick = async () => {
      const err = $("#evErr"), miss = [!$("#nt").value.trim() && "the finding", !$("#nr").value.trim() && "a reference"].filter(Boolean);
      if (miss.length) { err.hidden = false; err.textContent = `Add ${miss.join(" and ")} before saving. Every piece of evidence needs a reference someone else can check.`; ($("#nt").value.trim() ? $("#nr") : $("#nt")).focus(); return; }
      err.hidden = true; const btn = $("#addEv"); btn.disabled = true;
      try { await Svc.addEvidence(C.id, { kind: $("#nk").value, text: $("#nt").value, reference: $("#nr").value, source_date: $("#nsd").value.trim() || null, media_id: $("#nm").value || null, uncertainty: $("#nu").value || null, links: linksOf("new") }); toast("Evidence added."); await reload(); }
      catch (e) { err.hidden = false; err.textContent = errMsg(e); btn.disabled = false; }
    };
  }
  async function correctEvidence(e) {
    const own = e.origin === "analyst";
    const body = `${own ? `<p class="small muted" style="margin-top:0">The current wording is kept in the evidence history and in the case audit trail.</p><label class="f" for="ceT">Finding</label><textarea id="ceT" rows="4">${esc(e.text)}</textarea><label class="f" for="ceR">Reference</label><input type="text" id="ceR" value="${esc(e.reference)}">`
      : `<p class="small muted" style="margin-top:0">${e.origin === "ai" ? "AI" : "Automated"} suggestions keep their original wording. You can record the date the underlying source carries.</p>`}
      <label class="f" for="ceD">Source date</label><input type="text" id="ceD" value="${esc(e.source_date || "")}" placeholder="2018-10-14"><div class="hint">Year, year-month or full date. Leave empty if unknown.</div>`;
    const r = await modal(own ? `Correct ${e.id}` : `Source date for ${e.id}`, body, [{ label: "Cancel", value: null }, { label: "Save", kind: "primary", value: true,
      validate: async el => { try { await Svc.updateEvidence(C.id, e.id, { ...(own ? { text: $("#ceT", el).value, reference: $("#ceR", el).value } : {}), source_date: $("#ceD", el).value.trim() || null }); } catch (er) { return errMsg(er); } } }]);
    if (r.value) { toast(`${e.id} updated.`); await reload(); }
  }

  // ---------------------------------------------------------------- reverse image search (done by the analyst, outside AIVS)
  async function webSearch(m) {
    const sites = [["Google Lens", "https://lens.google.com/"], ["Bing Visual Search", "https://www.bing.com/visualsearch"], ["TinEye", "https://tineye.com/"], ["Yandex Images", "https://yandex.com/images/"]];
    const body = `<div class="callout warn"><div><b>This step leaves AIVS.</b> You upload the image to an outside search service yourself. Do it only for material that is already public or cleared for external search. ${LOCAL ? "AIVS itself sends nothing." : ""}</div></div>
      <ol class="small" style="margin:12px 0 0 18px;line-height:1.7"><li>${PL.downloads ? `<button class="btn sm" id="wsSave">Save a copy of ${esc(m.id)}</button> (the original bytes, unchanged).` : "Use the copy you received."}</li>
        <li>Open one or more services and upload the copy: ${sites.map(([n, u]) => `<a href="${u}" target="_blank" rel="noopener noreferrer">${n}</a>`).join(" · ")}</li>
        <li>Look for the <b>earliest</b> appearance, its date and who posted it. Note different captions for the same picture.</li><li>Record what you found below. Leave the date empty if the page does not show one.</li></ol>
      ${P.edit ? `<div class="grid g2" style="margin-top:12px"><div><label class="f" for="wsS">Service and search date</label><input type="text" id="wsS" value="${esc(`Reverse image search, ${new Date().toISOString().slice(0, 10)}`)}"></div><div><label class="f" for="wsD">Date of the earliest copy found</label><input type="text" id="wsD" placeholder="2018-10-14"></div></div>
      <label class="f" for="wsF">What you found</label><textarea id="wsF" rows="3" placeholder="e.g. Earliest copy found: news site X, 14 Oct 2018, captioned as a convoy crossing in Garissa. URL: …"></textarea>
      <label class="check" style="margin-top:8px"><input type="checkbox" id="wsNone"> Nothing relevant found (recorded as a lead, not as proof that the image is new)</label>` : ""}`;
    const r = await modal(`Search the web for ${m.id}`, body, [{ label: P.edit ? "Cancel" : "Close", value: null }, ...(P.edit ? [{ label: "Record result", kind: "primary", value: true, validate: async el => {
      const none = $("#wsNone", el).checked, txt = $("#wsF", el).value.trim(), svc = $("#wsS", el).value.trim();
      if (!none && !txt) return "Describe what you found, or tick “Nothing relevant found”.";
      if (!svc) return "Say which service you used and when.";
      try { await Svc.addEvidence(C.id, { kind: "lead", media_id: m.id, text: none ? `Reverse image search for ${m.id} found no relevant earlier copy. This does not show that the image is new or authentic.` : `Reverse image search for ${m.id}: ${txt}`, reference: svc, source_date: none ? null : ($("#wsD", el).value.trim() || null) }); }
      catch (e) { return errMsg(e); } } }] : [])], { onOpen: el => { const s = $("#wsSave", el); if (s) s.onclick = async () => { try { const blob = await (await fetch(m.url)).blob(); await PL.downloads.save({ filename: m.name || `${m.id}.jpg`, data: blob }); } catch (e) { if (!["declined", "cancelled"].includes(e?.code)) fail(e); } }; } });
    if (r.value) { toast("Search result recorded as accepted evidence (lead). Link it to the claims it bears on."); await reload(); }
  }

  // ---------------------------------------------------------------- notes (team discussion)
  function notes(body) {
    const one = n => n.deleted ? `<div class="note-item deleted"><span class="small sub">Note deleted ${ago(n.edited_at)}.</span></div>`
      : `<div class="note-item"><div class="row"><b>${esc(N(n.author))}</b><span class="tiny sub" title="${esc(fmtDT(n.created_at))}">${ago(n.created_at)}</span>${n.revision !== C.revision ? `<span class="chip grey">revision ${n.revision}</span>` : ""}${n.edited_at ? `<span class="tiny sub">· edited ${ago(n.edited_at)}</span>` : ""}
        <span class="right row">${n.author === PL.uid ? `<button class="btn sm ghost" data-ne="${esc(n.id)}">Edit</button>` : ""}${n.author === PL.uid || myRole() === "admin" ? `<button class="btn sm ghost" data-nd="${esc(n.id)}">Delete</button>` : ""}</span></div>
        <div class="note-body">${esc(n.body)}</div>${n.versions?.length ? `<details class="small"><summary class="sub">Earlier wording (${n.versions.length})</summary>${n.versions.slice().reverse().map(v => `<div class="ev-old"><div class="tiny sub">Replaced ${fmtDT(v.replaced_at)}</div>${esc(v.body)}</div>`).join("")}</details>` : ""}</div>`;
    const w = can("note.write");
    body.innerHTML = `<div class="card"><div class="hd"><h3>Team notes</h3><span class="small sub right">Internal working notes shared with everyone on this page. They never appear in reports.</span></div><div class="bd">
      ${NOTES.length ? `<div class="notes">${NOTES.map(one).join("")}</div>` : `<p class="muted small">No notes yet. Use notes to hand over work, ask a reviewer a question or record a decision.</p>`}
      ${w ? `<label class="f" for="nb">Add a note</label><textarea id="nb" rows="3" maxlength="4000" placeholder="e.g. Contacted the unit press office at 10:40; awaiting a reply."></textarea><div id="nbErr" class="callout bad" style="margin-top:8px" hidden></div><div style="margin-top:10px"><button class="btn primary" id="nbAdd">Add note</button></div>`
        : `<p class="small sub">Your role can read notes but not write them.</p>`}</div></div>`;
    if (w) $("#nbAdd").onclick = async () => {
      const t = $("#nb").value.trim(), err = $("#nbErr");
      if (!t) { err.hidden = false; err.textContent = "Write something before adding the note."; $("#nb").focus(); return; }
      const b = $("#nbAdd"); b.disabled = true;
      try { await Svc.addNote(C, t); toast("Note added."); await reload(); } catch (e) { err.hidden = false; err.textContent = errMsg(e); b.disabled = false; }
    };
    $$("[data-ne]").forEach(b => b.onclick = async () => {
      const n = NOTES.find(x => x.id === b.dataset.ne);
      const r = await modal("Edit note", `<p class="small muted" style="margin-top:0">The earlier wording stays visible under the note.</p><textarea id="neT" rows="5" maxlength="4000">${esc(n.body)}</textarea>`, [{ label: "Cancel", value: null }, { label: "Save", kind: "primary", value: true,
        validate: async el => { try { await Svc.editNote(n, $("#neT", el).value); } catch (e) { return errMsg(e); } } }]);
      if (r.value) { toast("Note updated."); await reload(); }
    });
    $$("[data-nd]").forEach(b => b.onclick = async () => { const n = NOTES.find(x => x.id === b.dataset.nd); if (await confirmBox("Delete note", "The note will be removed from the case for everyone.", "Delete note", "danger")) act(() => Svc.deleteNote(n), "Note deleted."); });
  }

  // ---------------------------------------------------------------- AI
  function ai(body) {
    const imgs = C.media.filter(m => m.kind === "image"), runs = [...(C.aiRuns || [])].reverse();
    body.innerHTML = `<div class="split"><div class="stack"><div class="card"><div class="hd"><h3>AI assistance</h3>${PL.sample ? `<span class="chip teal right">Available</span>` : `<span class="chip grey right">AI not configured</span>`}</div><div class="bd">
      <div class="callout info"><div><b>Local and cloud processing are separate.</b> Archive matching, metadata, hashing and claim extraction run in your browser. ${LOCAL ? "In this no-install edition nothing is sent to any cloud service." : "AI assistance sends the case content you select to Claude (Anthropic) through claude.ai on your account, only when you confirm."}</div></div>
      ${PL.sample ? `<p class="small muted" style="margin-top:12px">Claude can extract claims and entities, transcribe and describe visible content with stated uncertainty, suggest gaps and next checks, and draft a summary from evidence already in the case. Replies are checked against a fixed schema; replies citing evidence that does not exist are rejected. Nothing is applied until you accept it. Prompt version <span class="mono">${PROMPT_VERSION}</span>.</p>` : `<p style="margin-top:12px"><b>AI not configured${LOCAL ? " in the no-install edition: there is no server to keep an API key safe, so nothing is ever sent to a cloud service from here. Use the team edition for cloud AI." : " for this view."}</b> All local verification features keep working.</p>`}</div></div>
      ${PL.sample && P.ai ? `<div class="card"><div class="hd"><h3>Choose what to send</h3></div><div class="bd">${imgs.length ? `<div class="label">Images (up to 6)</div><div class="frames">${imgs.map((m, i) => `<label><figure><img src="${esc(m.url)}" alt=""><figcaption><input type="checkbox" data-aim="${esc(m.id)}" ${i < 2 && !m.parent ? "checked" : ""}> ${esc(m.id)}</figcaption></figure></label>`).join("")}</div>` : `<p class="small muted">No images in this case. The text and evidence can still be sent.</p>`}
        <label class="check" style="margin-top:10px"><input type="checkbox" id="aiOcr" checked> Include checked visible text for the selected images</label><label class="check"><input type="checkbox" id="aiEv" checked> Include evidence items (so Claude can cite them by ID)</label>
        <div class="row" style="margin-top:12px"><button class="btn" id="aiPrev">Preview what will be sent</button></div><div id="aiPv"></div></div></div>` : ""}</div>
      <div class="stack"><div class="card"><div class="hd"><h3>AI runs</h3><span class="chip grey right">${runs.length}</span></div><div class="bd">${runs.length ? runs.map(runCard).join("") : `<p class="small muted">No AI requests for this case.</p>`}</div></div></div></div>`;
    if ($("#aiPrev")) $("#aiPrev").onclick = async () => {
      const opts = { media_ids: $$("[data-aim]:checked").map(x => x.dataset.aim), include_ocr: $("#aiOcr").checked, include_evidence: $("#aiEv").checked };
      try { const p = await buildAIPayload(C, opts), s = p.sent;
        $("#aiPv").innerHTML = `<div class="panel" style="margin-top:12px"><b>This request would send to ${esc(s.destination)}:</b><ul class="small" style="margin:6px 0 0;padding-left:18px"><li>The working claim text, source and dates (${s.text_chars.toLocaleString()} characters including the rules)</li><li>${s.claim_ids.length} claim(s) and ${s.evidence_ids.length} evidence item(s) with their IDs</li><li>${s.media_ids.length} image(s), resized to at most 1568 px (${kb(s.image_bytes)})</li><li>Visible text from ${s.ocr_media_ids.length} record(s)</li></ul>
          ${p.flags.length ? `<div class="callout warn" style="margin-top:8px"><div>The content contains text that addresses AI systems (${p.flags.map(x => `“${esc(x)}”`).join(", ")}). It is sent as data to examine; Claude is instructed never to follow it.</div></div>` : ""}
          <details style="margin-top:8px"><summary class="small">Show the exact text</summary><pre class="box">${esc(p.text)}</pre></details>
          <label class="check" style="margin-top:10px"><input type="checkbox" id="aiOk"> I confirm this case content may be sent to Claude. The request and its fingerprint are recorded in the case audit trail.</label><button class="btn primary" id="aiSend" style="margin-top:10px" disabled>Send to Claude</button></div>`;
        $("#aiOk").onchange = e => ($("#aiSend").disabled = !e.target.checked);
        $("#aiSend").onclick = async () => { $("#aiSend").disabled = true; $("#aiSend").innerHTML = '<span class="spin"></span> Waiting for Claude…'; await act(() => runAI(C.id, opts), "AI run finished. Review the result under AI runs."); };
      } catch (e) { fail(e); }
    };
    $$("[data-apply]").forEach(b => b.onclick = () => act(() => applyAI(C.id, b.dataset.apply, b.dataset.type, +b.dataset.i || 0), b.dataset.type === "observation" ? "Accepted as evidence. Link it to claims on the Evidence tab." : "Added."));
  }
  function runCard(r) {
    const o = r.response, ok = P.ai && r.status === "completed";
    const chip = { running: `<span class="chip info"><span class="spin"></span> Running</span>`, completed: `<span class="chip sup">Validated</span>`, rejected: `<span class="chip con">Rejected</span>`, failed: `<span class="chip con">Failed</span>` }[r.status];
    return `<div class="panel" style="margin-bottom:10px"><div class="row"><b class="mono small">${esc(r.id)}</b>${chip}<span class="tiny sub" style="margin-left:auto">${fmtDT(r.started_at)}${r.duration_ms != null ? ` · ${(r.duration_ms / 1000).toFixed(1)} s` : ""}</span></div>
      <div class="tiny sub" style="margin-top:4px">${esc(r.provider)} · <span class="mono">${esc(r.model)}</span> · prompt ${esc(r.prompt_version)} · requested by ${esc(N(r.requested_by))} · sent ${r.sent.media_ids.length} image(s), ${r.sent.evidence_ids.length} evidence item(s)</div>
      ${r.injection_flags?.length ? `<div class="tiny" style="color:var(--warn);margin-top:4px">Instruction-like text was present in the content and was sent as data only.</div>` : ""}
      ${r.status === "failed" ? `<div class="callout bad" style="margin-top:8px"><div>${esc(r.error)}</div></div>` : ""}
      ${r.status === "rejected" ? `<div class="callout bad" style="margin-top:8px"><div><b>The reply was rejected and none of it can be used.</b><ul class="problems small">${r.validation_errors.map(x => `<li>${esc(x)}</li>`).join("")}</ul></div></div>` : ""}
      ${r.status === "completed" && o ? `${o.claims.length ? `<h4 style="margin-top:10px">Claims</h4>${o.claims.map((x, i) => `<div class="ev"><div class="small">${esc(x.text)} <span class="chip grey">${esc(x.kind)}</span>${x.existing_claim_id ? ` <span class="tiny sub">matches ${esc(x.existing_claim_id)}</span>` : ""}</div>${x.entities?.length ? `<div class="tiny sub">${x.entities.map(e => `${esc(e.type)}: ${esc(e.value)}`).join(" · ")}</div>` : ""}${x.supporting_evidence_ids.length || x.conflicting_evidence_ids.length ? `<div class="tiny">Supports: ${esc(x.supporting_evidence_ids.join(", ") || "—")} · Conflicts: ${esc(x.conflicting_evidence_ids.join(", ") || "—")}</div>` : ""}${ok && !x.existing_claim_id ? `<button class="btn sm" data-apply="${esc(r.id)}" data-type="claim" data-i="${i}" style="margin-top:6px">Add as claim</button>` : ""}</div>`).join("")}` : ""}
        ${o.observations.length ? `<h4 style="margin-top:10px">Observations</h4>${o.observations.map((x, i) => `<div class="ev"><div class="small"><span class="mono">${esc(x.media_id)}</span> <span class="chip grey">${x.kind === "visible_text" ? "visible text" : "visible content"}</span> <span class="chip warn">uncertainty ${esc(x.uncertainty)}</span></div><div class="small" style="margin-top:4px">${esc(x.description)}</div>${x.basis ? `<div class="tiny sub">Basis: ${esc(x.basis)}</div>` : ""}${ok ? `<button class="btn sm" data-apply="${esc(r.id)}" data-type="observation" data-i="${i}" style="margin-top:6px">Accept as evidence</button>` : ""}</div>`).join("")}` : ""}
        ${o.uncertainties.length ? `<h4 style="margin-top:10px">Uncertainties</h4><ul class="small problems">${o.uncertainties.map(x => `<li>${esc(x)}</li>`).join("")}</ul>` : ""}
        ${o.next_checks.length ? `<h4 style="margin-top:10px">Suggested next checks</h4>${o.next_checks.map((x, i) => `<div class="row small" style="margin-top:4px"><span style="flex:1">${esc(x)}</span>${ok ? `<button class="btn sm ghost" data-apply="${esc(r.id)}" data-type="check" data-i="${i}">Add to checklist</button>` : ""}</div>`).join("")}` : ""}
        ${o.summary_draft ? `<h4 style="margin-top:10px">Summary draft</h4><pre class="box">${esc(o.summary_draft)}</pre>${ok ? `<button class="btn sm" data-apply="${esc(r.id)}" data-type="summary" style="margin-top:6px">Use as briefing draft</button>` : ""}` : ""}` : ""}</div>`;
  }

  // ---------------------------------------------------------------- conclusion, review and report
  function report(body) {
    const ed = P.edit && C.status === "analyst_review", exp = expectedConclusion(C.claims), ready = Svc.readiness(C);
    body.innerHTML = `<div class="split"><div class="stack"><div class="card"><div class="hd"><h3>Overall conclusion</h3>${C.conclusion ? concl(C.conclusion) : ""}</div><div class="bd">
      ${exp ? `<div class="callout ${exp === "mixed" ? "warn" : "info"}"><div>From the claim assessments, the conclusion should be <b>${esc(CONCL[exp][0])}</b>.${exp === "mixed" ? " The content contains both supported and contradicted claims." : ""}</div></div>` : `<div class="callout info"><div>Assess every claim first (Claims tab). The overall conclusion follows from them.</div></div>`}
      <label class="f" for="cc">Conclusion</label><select id="cc" ${ed ? "" : "disabled"}><option value="">Choose…</option>${Object.entries(CONCL).map(([k, [l]]) => `<option value="${k}" ${C.conclusion === k ? "selected" : ""}>${l}</option>`).join("")}</select>
      <label class="f" for="cr">Reasoning <span class="req">*</span></label><textarea id="cr" rows="4" ${ed ? "" : "disabled"} placeholder="How the evidence leads to this conclusion. Distinguish what was observed from what is inferred.">${esc(C.conclusion_rationale || "")}</textarea>
      <label class="f" for="cu">Remaining uncertainties <span class="req">*</span></label><textarea id="cu" rows="3" ${ed ? "" : "disabled"} placeholder="What is still unknown and what would resolve it. Write “None identified” if there are none.">${esc(C.uncertainties || "")}</textarea>
      <div class="row" style="margin-top:12px"><label class="f" for="cb" style="margin:0">Summary for briefing</label>${ed ? `<button class="btn sm ghost" id="draftB" style="margin-left:auto">Draft from accepted evidence</button>` : ""}<button class="btn sm ghost" id="copyB">Copy</button></div>
      <textarea id="cb" rows="7" ${ed ? "" : "disabled"} style="margin-top:6px;font-family:var(--mono);font-size:12.5px">${esc(C.brief || "")}</textarea>${ed ? `<div class="row" style="margin-top:12px"><button class="btn primary" id="saveC">Save</button></div>` : ""}</div></div></div>
      <div class="stack">${C.status === "analyst_review" ? `<div class="card"><div class="hd"><h3>Submit for approval</h3></div><div class="bd">${ready.ok ? `<div class="callout good"><div><b>Ready.</b> Every claim is assessed with a rationale and backed by evidence, all suggestions are reviewed, and the conclusion matches the claims.</div></div>` : `<div class="callout warn"><div><b>Not ready yet:</b><ul class="problems">${ready.problems.map(p => `<li>${esc(p)}</li>`).join("")}</ul></div></div>`}
        ${P.edit ? `<button class="btn primary" id="submitA" style="margin-top:12px" ${ready.ok ? "" : "disabled"}>Submit for approval</button><div class="hint">The case locks while a reviewer decides. A different person must approve it.</div>` : ""}</div></div>` : ""}
      ${C.status === "awaiting_approval" ? `<div class="card"><div class="hd"><h3>${LOCAL ? "Local acknowledgement" : "Reviewer decision"}</h3></div>${LOCAL ? `<div class="bd" style="padding-bottom:0"><div class="callout warn"><div>This edition has no sign-in, so no independent review is possible here. Acknowledging freezes the report and records it as a <b>local analyst acknowledgement</b> under the typed name ${esc(PL.me?.name || "")}, not as a verified approval.</div></div></div>` : ""}<div class="bd"><p class="small">Submitted by <b>${esc(N(C.submitted_by))}</b> ${fmtDT(C.submitted_at)}.</p>${P.approve ? `<p class="small muted">Read the draft report, check the claims and evidence, then decide. Approval freezes the report with a fingerprint.</p><label class="f" for="rc">Comment</label><textarea id="rc" rows="3" placeholder="Required when returning; optional when approving"></textarea><div class="row" style="margin-top:10px"><button class="btn primary" id="appr">${LOCAL ? "Acknowledge (local)" : "Approve"}</button><button class="btn" id="ret">Return to analyst</button></div>` : `<div class="callout info"><div>${P.ownWork ? "You analysed or submitted this case, so a different reviewer must decide it." : "Waiting for a reviewer."}</div></div>`}</div></div>` : ""}
      <div class="card"><div class="hd"><h3>Report</h3></div><div class="bd"><div class="row"><button class="btn" id="prev">Preview ${["approved", "archived"].includes(C.status) ? "current" : "draft"} report</button><button class="btn ghost" data-ex="html">HTML</button><button class="btn ghost" data-ex="json">JSON</button></div>
        ${C.reports?.length ? `<h4 style="margin-top:14px">Approved reports</h4><ul class="mini">${C.reports.map(r => `<li><span class="mono small">${esc(r.id)}</span><span class="tiny sub" style="flex:1">${fmtDT(r.created_at)} · SHA-256 ${esc(r.sha256.slice(0, 12))}…</span><button class="btn sm" data-rep="${esc(r.id)}">View</button></li>`).join("")}</ul>` : `<p class="small muted" style="margin-top:10px">An approved report is frozen here when a reviewer approves the case.</p>`}</div></div></div></div>`;
    const data = () => reportData(C, N);
    $("#prev").onclick = () => showReport(data(), ["approved", "archived"].includes(C.status), `${C.id} · ${["approved", "archived"].includes(C.status) ? "current" : "draft"}`);
    $$("[data-ex]").forEach(b => b.onclick = () => exportReport(data(), ["approved", "archived"].includes(C.status), b.dataset.ex, `${C.id}-${["approved", "archived"].includes(C.status) ? "current" : "draft"}`));
    $$("[data-rep]").forEach(b => b.onclick = async () => { const r = await Svc.getReport(b.dataset.rep); showReport(JSON.parse(r.json), true, `${r.id} · SHA-256 ${r.sha256.slice(0, 16)}…`); });
    $("#copyB").onclick = () => { navigator.clipboard?.writeText($("#cb").value).then(() => toast("Summary copied."), () => { $("#cb").select(); toast("Press Ctrl+C to copy."); }); };
    if (ed) {
      $("#draftB").onclick = () => { $("#cb").value = draftBrief($("#cc").value, $("#cr").value, $("#cu").value); toast("Draft written. Edit it, then save."); };
      $("#saveC").onclick = () => act(() => Svc.updateCase(C.id, { conclusion: $("#cc").value || null, conclusion_rationale: $("#cr").value, uncertainties: $("#cu").value, brief: $("#cb").value }), "Saved.");
    }
    if ($("#submitA")) $("#submitA").onclick = async () => { if (await confirmBox("Submit for approval?", "The case will lock until a reviewer approves it or returns it to you.", "Submit")) act(() => Svc.submit(C.id), "Submitted for approval."); };
    if ($("#appr")) $("#appr").onclick = async () => { if (await (LOCAL ? confirmBox("Record a local acknowledgement?", "The report will be frozen with a SHA-256 fingerprint and labelled as a local analyst acknowledgement (typed name, no verified identity, no independent review).", "Acknowledge") : confirmBox("Approve this assessment?", "The report will be frozen with a SHA-256 fingerprint and recorded as approved by you.", "Approve"))) act(() => Svc.decide(C.id, "approve", $("#rc").value), (LOCAL ? "Local acknowledgement recorded. The report is frozen." : "Approved. The report is frozen.")); };
    if ($("#ret")) $("#ret").onclick = () => { if (!$("#rc").value.trim()) return toast("Say what needs to change before returning the case.", "err"); act(() => Svc.decide(C.id, "return", $("#rc").value), "Returned to the analyst."); };
  }
  function draftBrief(conclusion, rationale, unc) {
    const acc = C.evidence.filter(e => e.status === "accepted"), L = [`Assessment: ${CONCL[conclusion]?.[0]?.toUpperCase() || "NOT YET CONCLUDED"} (draft, not approved)`, `Content: “${C.claim_text.trim()}”`, `Seen on ${C.source_platform}; received ${fmtDT(C.received_at)}. Case ${C.id}.`, "", "Claim by claim:"];
    for (const cl of C.claims.filter(x => !x.removed)) { const ev = acc.filter(e => (e.links || []).some(l => l.claim_id === cl.id && l.stance !== "context")).map(e => e.id); L.push(`${cl.seq}. ${cl.text} — ${ASSESS[cl.assessment][0]}${ev.length ? ` [${ev.join(", ")}]` : ""}`); }
    if (rationale) L.push("", `Reasoning: ${rationale}`); if (unc) L.push(`Uncertainties: ${unc}`);
    if (conclusion === "contradicted" || conclusion === "mixed") L.push("", "Handling: do not repeat the contradicted parts as fact. Any correction should cite the earliest documented source.");
    if (conclusion === "insufficient") L.push("", "Handling: report as unverified and seek confirmation from the named source before use.");
    return L.join("\n");
  }

  // ---------------------------------------------------------------- history
  async function history(body) {
    const vs = await Svc.versions(C.id), chain = await verifyCaseChain(C);
    body.innerHTML = `<div class="split"><div class="card"><div class="hd"><h3>Versions</h3><span class="small sub right">Every change saves a full snapshot</span></div><div class="tablewrap"><table class="t"><thead><tr><th>Version</th><th>Change</th><th>By</th><th>When</th><th></th></tr></thead><tbody>${vs.map(v => `<tr><td class="num">${v.version}<div class="tiny sub">rev ${v.revision}</div></td><td class="small">${esc(v.reason)}</td><td class="small">${esc(N(v.by))}</td><td class="small sub">${fmtDT(v.at)}</td><td><button class="btn sm ghost" data-ver="${v.version}">View</button></td></tr>`).join("")}</tbody></table></div></div>
      <div class="card"><div class="hd"><h3>Audit trail</h3>${chain.ok ? `<span class="chip sup right">Chain intact · ${chain.checked} entries</span>` : `<span class="chip con right">Chain broken at entry ${chain.brokenAt + 1}</span>`}</div><div class="bd"><ul class="mini">${[...C.audit].reverse().map(a => `<li><span class="tiny sub" style="width:130px;flex:none">${fmtDT(a.at)}</span><span class="small"><b>${esc(a.uid ? N(a.uid) : "system")}</b> · ${esc(a.action)}</span></li>`).join("")}</ul></div></div></div>`;
    $$("[data-ver]").forEach(b => b.onclick = () => { const v = vs.find(x => x.version === +b.dataset.ver), k = JSON.parse(v.snapshot);
      modal(`Version ${v.version} · ${v.reason}`, `<p class="small muted">Saved ${fmtDT(v.at)} by ${esc(N(v.by))}.</p><dl class="kv"><dt>Status</dt><dd>${esc(STATUS[k.status])}</dd><dt>Title</dt><dd>${esc(k.title)}</dd><dt>Working text</dt><dd>${esc(k.claim_text)}</dd><dt>Conclusion</dt><dd>${esc(CONCL[k.conclusion]?.[0] || "—")}</dd><dt>Reasoning</dt><dd>${esc(k.conclusion_rationale || "—")}</dd><dt>Uncertainties</dt><dd>${esc(k.uncertainties || "—")}</dd></dl>
        <h4 style="margin-top:12px">Claims</h4><ul class="small">${(k.claims || []).filter(x => !x.removed).map(x => `<li>${esc(x.text)} — <b>${esc(ASSESS[x.assessment][0])}</b></li>`).join("")}</ul><p class="small">${(k.evidence || []).filter(e => e.status === "accepted").length} accepted evidence item(s).</p><details><summary class="small">Full snapshot (JSON)</summary><pre class="box">${esc(JSON.stringify(k, null, 2))}</pre></details>`, [{ label: "Close" }], { wide: true }); });
  }
  draw();
}
